<template><scroll-view scroll-y class="page"><text class="title">官方路线资料审核</text><text>需要服务器已授权的管理员账号。官方来源域名由服务端配置；所有审核状态最多七天后回到待核验；可导航轨迹需另行核对来源、许可和连续性。</text><text>{{accessMessage}}</text><CatalogReviewInventory v-if="accessState==='allowed'" :disabled="busy" @select="choose($event.id,$event.name)" /><button v-if="accessState === 'login-required'" @click="openAccountLogin">登录或关联账号</button><view v-if="accessState === 'allowed'" class="audit-queue"><text class="queue-title">路线来源风险与变更复核</text><text>{{remoteAccessMessage}}</text><text v-if="remoteAccessCount">发现 {{remoteAccessCount}} 条 · 展示 {{remoteAccessListed}} 条{{remoteAccessTruncated ? ' · 队列已截断，未展示候选尚未逐条复核' : ''}}</text><text v-if="remoteAccessGeneratedAt">扫描时间：{{remoteAccessGeneratedAt}}</text><text class="notice">自动扫描覆盖已配置的公开目录，只用于风险筛查；来源标签不是官方通行公告，也不会自动关闭路线或授予导航权限。逐条核对官方资料后再提交审核。</text><view v-for="(r,index) in remoteAccessCandidates" :key="`remote-access-${remoteAccessPage}-${index}`" class="remote-candidate"><text>{{r.name || r.routeId}} · {{r.region || '地区待核'}}</text><text>发现来源：{{r.sourceLabel}} · {{r.sourceUrl}}</text><button :disabled="busy" @click="copySource(r.sourceUrl)">复制来源链接</button><text v-if="hasMembershipChange(r)">{{r.membershipReviewStatus === 'reviewed-after-change' ? '来源变更已按有效官方资料复核' : '来源变更待复核（无有效审核记录）'}} · {{r.membershipCheckedAt || r.sourceChangeAt}}</text><text v-for="(finding,index) in r.findings" :key="`${r.routeId}-${index}`">{{finding.reason === 'source-membership-change' ? '来源成员关系变更待核' : '访问风险信号待核'}}：{{finding.field}} = {{finding.value}}</text><button :disabled="busy" @click="choose(r.routeId,r.name)">核对官方资料并审核</button></view><view v-if="remoteAccessHasMore || remoteAccessPage > 0" class="queue-pages"><button :disabled="remoteAccessPage <= 0" @click="loadRemoteAccessCandidates(remoteAccessPage-1)">上一页</button><text>第 {{remoteAccessPage+1}} 页</text><button :disabled="!remoteAccessHasMore" @click="loadRemoteAccessCandidates(remoteAccessPage+1)">下一页</button></view></view><text v-if="nameReviewCount">当前目录名称待核对：{{nameReviewCount}} 条（每页12条）</text><button v-for="r in nameReviewCandidates" :key="`name-review-${r.id}`" :disabled="busy || accessState !== 'allowed'" @click="choose(r.id)">名称待核对 · {{r.name}} · {{r.region}}</button><view v-if="nameReviewPageCount > 1" class="queue-pages"><button :disabled="safeNameReviewPage === 0" @click="nameReviewPage=Math.max(0,safeNameReviewPage-1)">上一页</button><text>第 {{safeNameReviewPage+1}} / {{nameReviewPageCount}} 页</text><button :disabled="safeNameReviewPage+1 >= nameReviewPageCount" @click="nameReviewPage=Math.min(nameReviewPageCount-1,safeNameReviewPage+1)">下一页</button></view><text v-if="accessReviewCount">来源访问限制候选：{{accessReviewCount}} 条（仅覆盖本机当前已加载目录；须核对官方公告，不自动改变状态）</text><button v-for="r in accessReviewCandidates" :key="`access-review-${r.id}`" :disabled="busy || accessState !== 'allowed'" @click="choose(r.id)">限制信号待复核 · {{r.name}} · {{r.region}} · {{accessReviewSignal(r)}}</button><view v-if="accessReviewPageCount > 1" class="queue-pages"><button :disabled="safeAccessReviewPage === 0" @click="accessReviewPage=Math.max(0,safeAccessReviewPage-1)">上一页</button><text>限制候选第 {{safeAccessReviewPage+1}} / {{accessReviewPageCount}} 页</text><button :disabled="safeAccessReviewPage+1 >= accessReviewPageCount" @click="accessReviewPage=Math.min(accessReviewPageCount-1,safeAccessReviewPage+1)">下一页</button></view><input :disabled="busy || accessState !== 'allowed'" v-model="keyword" placeholder="搜索路线" /><button v-for="r in matching" :key="r.id"  :disabled="busy || accessState !== 'allowed'" @click="choose(r.id)">{{r.name}} · {{r.region}}</button><text>路线 {{routeName||'未选择'}}</text><picker :disabled="busy || accessState !== 'allowed'" :range="statuses" :value="statuses.indexOf(status)" @change="status=statuses[Number(eventValue($event))]"><button>状态：{{status}}</button></picker><text class="notice">此处只填写官方公告或权属资料。发现目录来源（包括地图对象和原始状态标签）不能证明当前开放、通行许可或导航安全。</text><input :disabled="busy || accessState !== 'allowed'" v-model="sourceUrl" placeholder="官方 HTTPS 开放公告或权属资料链接" /><input :disabled="busy || accessState !== 'allowed'" v-model="checkedAt" placeholder="核验日期，如 2026-10-05T00:00:00+08:00" /><textarea :disabled="busy || accessState !== 'allowed'" v-model="summary" maxlength="3000" placeholder="资料摘要" /><textarea :disabled="busy || accessState !== 'allowed'" v-model="riskNotice" maxlength="3000" placeholder="风险与预约提示" /><view><text>可选：独立审核可导航轨迹。不得直接使用简化参考线、认知示意或中断路线。</text><input :disabled="busy || accessState !== 'allowed'" v-model="trackSource" placeholder="轨迹官方来源 HTTPS 链接" /><input :disabled="busy || accessState !== 'allowed'" v-model="trackLicense" placeholder="适用许可及依据（不填则不开放轨迹）" /><textarea :disabled="busy || accessState !== 'allowed'" v-model="trackJson" :maxlength="2097152" placeholder="连续完整 WGS84 点列 JSON：[[经度,纬度],...]" /><switch :color="HE_PALETTE.accent" :disabled="busy || accessState !== 'allowed'" :checked="trackConfirmed" @change="trackConfirmed=eventValue($event)" /><text>确认已核验许可、完整轨迹及连续性</text></view><button v-if="hasExistingTrack" :disabled="busy || accessState !== 'allowed'" @click="removeTrack">明确移除已有轨迹</button><text>{{message}}</text><button :disabled="busy || accessState !== 'allowed' || !routeId" @click="save">提交审核资料</button></scroll-view></template>
<script setup lang="ts">
import CatalogReviewInventory from '@/components/CatalogReviewInventory.vue';
import { HE_PALETTE } from '@shared/design/palette';
function eventValue(event: Event): any { return (event as Event & {detail:{value:unknown}}).detail.value; }
import {onShow,onHide,onUnload} from '@dcloudio/uni-app';import {accountSession,onAccountChange} from '@/services/account';import {ref,computed} from 'vue';import {ROUTES} from '@/services/route-catalog';import {callCloud} from '@/services/cloud';import type {RouteStatus} from '@shared/types/route';
const keyword=ref(''),routeId=ref(''),selectedRouteName=ref(''),sourceUrl=ref(''),checkedAt=ref(new Date().toISOString()),summary=ref(''),riskNotice=ref(''),status=ref<RouteStatus>('待核验'),trackSource=ref(''),trackLicense=ref(''),trackJson=ref(''),trackConfirmed=ref(false),version=ref(0),message=ref(''),busy=ref(false),accessState=ref<'checking'|'login-required'|'denied'|'allowed'>('checking'),accessMessage=ref('正在核验管理员权限…');let selection=0,visible=false,accessGeneration=0;const hasExistingTrack=ref(false);
type RemoteAccessCandidate={sourceId:string;sourceLabel:string;routeId:string;name:string;region:string;sourceUrl:string;sourceChangeAt?:string;membershipReviewStatus?:'pending'|'reviewed-after-change';membershipCheckedAt?:string|null;findings:{field:string;value:string;reason:string}[];disposition:'human-review-required'};
const remoteAccessCandidates=ref<RemoteAccessCandidate[]>([]),remoteAccessSnapshot=ref(''),remoteAccessCount=ref(0),remoteAccessListed=ref(0),remoteAccessTruncated=ref(false),remoteAccessGeneratedAt=ref(''),remoteAccessPage=ref(0),remoteAccessHasMore=ref(false),remoteAccessMessage=ref('正在等待管理员权限核验…');let auditGeneration=0;
function invalidate(){selection++;busy.value=false;routeId.value='';selectedRouteName.value='';hasExistingTrack.value=false;trackJson.value='';trackSource.value='';trackLicense.value='';trackConfirmed.value=false;summary.value='';riskNotice.value='';sourceUrl.value='';message.value='';}
function clearRemoteAccess(messageText='等待管理员权限核验…'){auditGeneration++;remoteAccessCandidates.value=[];remoteAccessSnapshot.value='';remoteAccessCount.value=0;remoteAccessListed.value=0;remoteAccessTruncated.value=false;remoteAccessGeneratedAt.value='';remoteAccessPage.value=0;remoteAccessHasMore.value=false;remoteAccessMessage.value=messageText;}
function safeRemoteCandidate(value:any):RemoteAccessCandidate|null {
 if(!value||typeof value!=='object'||! /^[a-z0-9][a-z0-9-]{0,63}$/.test(value.sourceId||'')||typeof value.sourceLabel!=='string'||value.sourceLabel.length>128||typeof value.routeId!=='string'||! /^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$/.test(value.routeId)||typeof value.name!=='string'||value.name.length>500||typeof value.region!=='string'||value.region.length>256||typeof value.sourceUrl!=='string'||value.sourceUrl.length>2048||value.disposition!=='human-review-required'||!Array.isArray(value.findings)||value.findings.length<1||value.findings.length>32)return null;
 try{const url=new URL(value.sourceUrl);if(url.protocol!=='https:'||!url.hostname||url.username||url.password||url.port)return null;}catch{return null;}
 const findings:{field:string;value:string;reason:string}[]=[];
 for(const finding of value.findings){if(!finding||typeof finding!=='object'||typeof finding.field!=='string'||finding.field.length>64||!['string','boolean'].includes(typeof finding.value)||typeof finding.value==='string'&&finding.value.length>240||!['negative-access-signal','source-membership-change'].includes(finding.reason)||finding.reason==='source-membership-change'&&(value.sourceId.indexOf('osm-pbf-')!==0||finding.field!=='sourceMembership'||!['source-released','catalog-removed'].includes(finding.value)))return null;findings.push({field:finding.field,value:String(finding.value),reason:finding.reason});}
 const hasMembershipChange=findings.some(finding=>finding.reason==='source-membership-change');
 if(hasMembershipChange&&(typeof value.sourceChangeAt!=='string'||value.sourceChangeAt.length>40||!Number.isFinite(Date.parse(value.sourceChangeAt))||value.membershipReviewStatus!==undefined&&!['pending','reviewed-after-change'].includes(value.membershipReviewStatus)||value.membershipCheckedAt!==undefined&&value.membershipCheckedAt!==null&&(typeof value.membershipCheckedAt!=='string'||!Number.isFinite(Date.parse(value.membershipCheckedAt)))))return null;
 return{sourceId:value.sourceId,sourceLabel:value.sourceLabel,routeId:value.routeId,name:value.name,region:value.region,sourceUrl:value.sourceUrl,...(hasMembershipChange?{sourceChangeAt:value.sourceChangeAt,membershipReviewStatus:value.membershipReviewStatus,membershipCheckedAt:value.membershipCheckedAt}:{}),findings,disposition:'human-review-required'};
}
function hasMembershipChange(candidate:RemoteAccessCandidate){return candidate.findings.some(finding=>finding.reason==='source-membership-change');}
function copySource(url:string){if(!url)return;uni.setClipboardData({data:url,success:()=>uni.showToast({title:'来源链接已复制',icon:'success'}),fail:()=>uni.showToast({title:'复制失败，请手动复制链接',icon:'none'})});}
async function loadRemoteAccessCandidates(page:number,refreshLatest=false){
 if(!visible||accessState.value!=='allowed'||!Number.isSafeInteger(page)||page<0||page>799)return;
 const generation=++auditGeneration,token=accountSession()?.token||'',snapshot=refreshLatest?'':remoteAccessSnapshot.value;
 remoteAccessMessage.value='正在读取定时来源扫描结果…';
 try{
  const request:any={action:'access-candidates',page};if(snapshot)request.snapshot=snapshot;
  const result=await callCloud<any>('route-manage',request);
  if(!visible||generation!==auditGeneration||accessState.value!=='allowed'||(accountSession()?.token||'')!==token)return;
  if(!result.ok||!result.data)throw new Error(result.errMsg||'云端扫描队列暂不可用');
  const data=result.data;
  if(data.changed===true){
   remoteAccessMessage.value='扫描结果已更新，正在从最新快照重新读取…';
   remoteAccessCandidates.value=[];remoteAccessSnapshot.value='';remoteAccessHasMore.value=false;
   if(!refreshLatest)await loadRemoteAccessCandidates(0,true);
   else throw new Error('扫描结果持续更新，请稍后重试');
   return;
  }
  if(data.available===false&&Array.isArray(data.items)&&data.items.length===0){clearRemoteAccess('云端尚无已发布的扫描快照；定时扫描结果仍保留在工作流附件中。');return;}
  const generated=typeof data.generatedAt==='string'?Date.parse(data.generatedAt):NaN;
  const expectedItems=Number.isSafeInteger(data.listed)?Math.min(25,Math.max(0,data.listed-page*25)):-1;
  if(data.available!==true||typeof data.snapshot!=='string'||! /^[a-f0-9]{64}$/.test(data.snapshot)||snapshot&&data.snapshot!==snapshot||!Number.isFinite(generated)||generated>Date.now()+5*60*1000||Date.now()-generated>72*60*60*1000||!Number.isSafeInteger(data.total)||data.total<0||!Number.isSafeInteger(data.listed)||data.listed<0||data.listed>20000||data.total<data.listed||!Number.isSafeInteger(data.sourceCount)||data.sourceCount<1||data.sourceCount>64||typeof data.truncated!=='boolean'||data.truncated!==(data.total>data.listed)||data.page!==page||typeof data.hasMore!=='boolean'||!Array.isArray(data.items)||data.items.length!==expectedItems||data.items.some((item:any)=>!safeRemoteCandidate(item))||data.hasMore!==(page*25+data.items.length<data.listed))throw new Error('云端扫描快照格式无效或已过期');
  remoteAccessCandidates.value=data.items.map((item:any)=>safeRemoteCandidate(item)!);remoteAccessSnapshot.value=data.snapshot;remoteAccessCount.value=data.total;remoteAccessListed.value=data.listed;remoteAccessTruncated.value=data.truncated;remoteAccessGeneratedAt.value=data.generatedAt;remoteAccessPage.value=page;remoteAccessHasMore.value=data.hasMore;remoteAccessMessage.value=data.listed?'队列包含来源访问风险和来源成员关系变更；所有项目都须人工核对官方资料，不会自动改变路线状态。':'最近一次扫描未发现来源访问风险或成员关系变更。';
 }catch(error){if(visible&&generation===auditGeneration){remoteAccessCandidates.value=[];remoteAccessMessage.value=error instanceof Error?`${error.message}；可查看定时工作流附件。`:'云端扫描队列暂不可用；可查看定时工作流附件。';}}
}
async function checkAccess(){if(!visible)return;const generation=++accessGeneration;const token=accountSession()?.token||'';accessState.value='checking';accessMessage.value='正在核验管理员权限…';try{const result=await callCloud<{canReview:boolean;ownerConfigured?:boolean}>('route-manage',{action:'capabilities'});if(!visible||generation!==accessGeneration||(accountSession()?.token||'')!==token)return;if(result.ok&&result.data?.canReview===true){accessState.value='allowed';accessMessage.value='服务器已确认当前身份具有路线审核权限。';void loadRemoteAccessCandidates(0,true);}else if(result.ok){accessState.value='denied';accessMessage.value=result.data?.ownerConfigured===false?'服务端尚未绑定唯一管理员账号；请在 CloudBase 配置 HIKING_ADMIN_IDENTITY。':'当前微信/账号没有审核权限；管理员身份必须由服务端配置。';clearRemoteAccess('管理员权限未通过，未显示扫描队列。');}else{accessState.value='login-required';accessMessage.value='请先登录徒步地球账号；登录后将由服务器核验管理员权限。';clearRemoteAccess('请先登录管理员账号。');}}catch{if(visible&&generation===accessGeneration){accessState.value='login-required';accessMessage.value='当前无法核验登录状态，请登录后重试。';clearRemoteAccess('无法核验管理员权限。');}}}
function openAccountLogin(){uni.navigateTo({url:'/pages/account/account'});}
const offAccount=onAccountChange(()=>{invalidate();clearRemoteAccess('账号已切换，重新核验管理员权限后读取。');void checkAccess();});onShow(()=>{visible=true;void checkAccess();});onHide(()=>{accessState.value='checking';visible=false;accessGeneration++;clearRemoteAccess('页面离开后已清除扫描候选。');invalidate();});onUnload(()=>{visible=false;accessGeneration++;clearRemoteAccess('页面已关闭。');invalidate();offAccount();});
function context(){const session=accountSession();return {selection,token:session?.token,route:routeId.value};}
function current(ctx:ReturnType<typeof context>){return visible&&selection===ctx.selection&&accountSession()?.token===ctx.token&&routeId.value===ctx.route;}
function removeTrack(){if(busy.value)return;hasExistingTrack.value=false;trackConfirmed.value=false;trackSource.value='';trackLicense.value='';trackJson.value='';message.value='本次保存将移除已有轨迹';}
const statuses:RouteStatus[]=['待核验','开放中','即将开放','临时关闭','永久关闭'];const matching=computed(()=>keyword.value?ROUTES.filter(r=>`${r.name} ${r.region}`.includes(keyword.value)).slice(0,10):[]);const nameReviewPage=ref(0);const nameReviewAll=computed(()=>ROUTES.filter(r=>r.archive.highlights.some(item=>item.startsWith('来源名称包含'))));const nameReviewCount=computed(()=>nameReviewAll.value.length);const nameReviewPageCount=computed(()=>Math.ceil(nameReviewCount.value/12));const safeNameReviewPage=computed(()=>Math.min(nameReviewPage.value,Math.max(0,nameReviewPageCount.value-1)));const nameReviewCandidates=computed(()=>nameReviewAll.value.slice(safeNameReviewPage.value*12,(safeNameReviewPage.value+1)*12));const accessReviewPage=ref(0);const accessReviewAll=computed(()=>ROUTES.filter(r=>r.archive.highlights.some(item=>item.startsWith('来源访问限制信号待复核：'))));const accessReviewCount=computed(()=>accessReviewAll.value.length);const accessReviewPageCount=computed(()=>Math.ceil(accessReviewCount.value/12));const safeAccessReviewPage=computed(()=>Math.min(accessReviewPage.value,Math.max(0,accessReviewPageCount.value-1)));const accessReviewCandidates=computed(()=>accessReviewAll.value.slice(safeAccessReviewPage.value*12,(safeAccessReviewPage.value+1)*12));const accessReviewSignal=(route:typeof ROUTES[number])=>route.archive.highlights.find(item=>item.startsWith('来源访问限制信号待复核：'))||'来源字段提示需复核';const routeName=computed(()=>ROUTES.find(r=>r.id===routeId.value)?.name||selectedRouteName.value);
async function choose(id:string,fallbackName=''){
 if(busy.value)return;invalidate();routeId.value=id;selectedRouteName.value=ROUTES.find(r=>r.id===id)?.name||fallbackName;keyword.value='';version.value=0;checkedAt.value=new Date().toISOString();const ctx=context();
 const route=ROUTES.find(r=>r.id===id);summary.value=route?.summary||'';riskNotice.value=route?.archive.riskNotice||'';sourceUrl.value='';status.value='待核验';busy.value=true;
 try{const result=await callCloud<{items:any[];hasMore:boolean}>('route-manage',{action:'list',routeId:id});if(!current(ctx))return;
  if(!result.ok||!result.data)throw new Error(result.errMsg||'读取审核版本失败');
  if(!Array.isArray(result.data.items)||result.data.items.length>1||result.data.hasMore!==false)throw new Error('审核资料格式无效');
  const prior=result.data.items[0];if(!prior)return;
  if(prior.routeId!==id||!Number.isInteger(prior.version)||prior.version<1||!statuses.includes(prior.status)||typeof prior.sourceUrl!=='string'||typeof prior.summary!=='string'||typeof prior.riskNotice!=='string'||!Number.isFinite(Date.parse(prior.checkedAt)))throw new Error('审核资料格式无效');
  version.value=prior.version;sourceUrl.value=prior.sourceUrl;summary.value=prior.summary;riskNotice.value=prior.riskNotice;status.value=prior.status;checkedAt.value=prior.checkedAt;
  if(prior.track){if(typeof prior.track.sourceUrl!=='string'||typeof prior.track.license!=='string'||!Array.isArray(prior.track.path))throw new Error('轨迹资料格式无效');hasExistingTrack.value=true;trackSource.value=prior.track.sourceUrl;trackLicense.value=prior.track.license;trackJson.value=JSON.stringify(prior.track.path);message.value='已有轨迹：保存前请核验并勾选连续性确认，或明确移除轨迹。';}
 }catch(e){if(current(ctx)){routeId.value='';message.value=e instanceof Error?e.message:'读取失败';}}finally{if(selection===ctx.selection)busy.value=false;}
}
async function save(){
 if(busy.value||!routeId.value)return;
 if(hasExistingTrack.value&&!trackConfirmed.value){message.value='请确认已有轨迹许可和连续性，或明确移除轨迹';return;}
 const ctx=context();const priorVersion=version.value;
 busy.value=true;message.value='';
 try{const track=trackConfirmed.value?{sourceUrl:trackSource.value,license:trackLicense.value,path:JSON.parse(trackJson.value),continuityConfirmed:true}:null;
  const result=await callCloud<{saved:boolean;version:number}>('route-manage',{action:'save',track,routeId:ctx.route,sourceUrl:sourceUrl.value,checkedAt:checkedAt.value,status:status.value,summary:summary.value,riskNotice:riskNotice.value,version:priorVersion});if(!current(ctx))return;
  if(!result.ok||result.data?.saved!==true||result.data.version!==priorVersion+1)throw new Error(result.errMsg||'保存未确认，请重新读取核对');
  version.value=result.data.version;hasExistingTrack.value=!!track;message.value='云端已确认保存；其他端刷新后获取，当前开放仍受有效期限制。';
 }catch(e){if(current(ctx))message.value=e instanceof Error?e.message:'保存失败';}finally{if(current(ctx))busy.value=false;}
}

</script><style scoped>.page{box-sizing:border-box;padding:15px;background:var(--he-color-background);color:var(--he-color-text);min-height:100vh}.title,.queue-title{font-size:18px;font-weight:700}.notice{padding:10px;border-radius:10px;background:var(--he-color-surface);color:var(--he-color-muted);line-height:1.5}.audit-queue{margin:14px 0;padding:12px;border:1px solid var(--he-color-border);border-radius:14px;background:var(--he-color-surface)}.remote-candidate{margin:10px 0;padding:10px;border:1px solid var(--he-color-border);border-radius:10px;background:var(--he-color-background)}.remote-candidate text{word-break:break-all}text{display:block;margin:10px 0}.queue-pages{display:flex;align-items:center;justify-content:space-between;gap:8px}.queue-pages text{margin:0;white-space:nowrap}input,textarea{padding:10px;background:var(--he-color-surface);margin:7.5px 0;width:100%;box-sizing:border-box}button{margin:7.5px 0}</style>
